    "hypotheses": [
      {
        "hypothesis_id": "ideal_981",
        "statement": "The rig follows the ideal small-angle pendulum law T = 2π√(L/g) with g = 9.81 m/s^2; mass and release angle have no effect.",
        "confidence": 0.55
      },
      {
        "hypothesis_id": "ideal_970",
        "statement": "The rig follows the same ideal small-angle pendulum law but with an effective local g = 9.70 m/s^2.",
        "confidence": 0.25
      },
      {
        "hypothesis_id": "constant_period",
        "statement": "The period is approximately independent of the controls and is about 2.70 s for this apparatus.",
        "confidence": 0.20
      }
    ]
  },
  "experiment": {
    "intent": "Measure the period at a long length and small angle to compare the absolute timing predictions of the ideal-pendulum hypotheses and a length-independent alternative.",
    "apparatus": "simple_pendulum",
    "controls": {
      "length_m": 2.0,
      "bob_mass_kg": 0.1,
      "release_angle_deg": 5.0
    },
    "readouts": [
      "period_s"
    ],
    "replicates": 20,
    "forecasts": {
      "ideal_981": 2.8370,
      "ideal_970": 2.8531,
      "constant_period": 2.7000
    }
  },
  "final": null
}

